INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('passage_reconstruction', '{"passage": "An airline noticed recurring delays at one of its busiest gates. Ground staff reviewed the boarding process and found it was too slow for large aircraft. They introduced zone-based boarding to speed things up. Average boarding time dropped by several minutes within weeks."}'::jsonb, '{"key_points": ["an airline noticed recurring delays at a gate", "staff found boarding was too slow", "they introduced zone-based boarding", "boarding time dropped within weeks"]}'::jsonb, 45, 0.55, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-000000000012', 1),
('passage_reconstruction', '{"passage": "A bus company kept receiving complaints about overcrowded routes during rush hour. Managers reviewed ridership data and found one route far exceeded capacity. They added extra buses during peak times only. Passenger complaints about that route decreased significantly."}'::jsonb, '{"key_points": ["a bus company received complaints about overcrowding", "one route exceeded capacity", "they added extra buses at peak times", "complaints decreased significantly"]}'::jsonb, 41, 0.56, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-000000000012', 2),
('passage_reconstruction', '{"passage": "Thank you for your patience regarding the recent flight delay. We understand this disrupted your travel plans, and we sincerely apologize for the inconvenience. As a gesture of goodwill, we have applied a travel credit to your account for use on a future booking."}'::jsonb, '{"key_points": ["thanks for patience with the flight delay", "apologizes for the disruption", "a travel credit was applied", "it can be used on a future booking"]}'::jsonb, 42, 0.56, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-000000000012', 3);
