('reading_comprehension', '{"passage": "Flight Status Board: Flight 204 departs 8am, on time. Flight 310 departs 9:15am, delayed 45 minutes. Flight 512 departs 11am, cancelled due to weather.", "question": "Which flight is delayed?", "options": ["Flight 204", "Flight 310", "Flight 512", "None of them"]}'::jsonb, '{"correctIndex": 1}'::jsonb, 0.46, 'B1', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-000000000013', 1),
