INSERT INTO items (item_type_id, content, answer_set, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('email_writing', '{"prompt": "Your airline has had an increase in complaints about boarding delays. Your manager, Mr. Fontaine, wants ideas for improving the boarding process without adding staff. Write an email to him suggesting three ways to achieve this. Your suggestions must come from the following three themes: zone-based boarding, clearer gate announcements, a dedicated priority lane. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-000000000014', 1),
('email_writing', '{"prompt": "Your transit company is planning to improve its customer communication during delays. Your manager, Ms. Abara, wants ideas for the update. Write an email to her suggesting three priorities for the change. Your suggestions must come from the following three themes: real-time app alerts, clearer station announcements, a customer support hotline. You should include all three themes and provide supporting ideas for each of your suggestions."}'::jsonb, null, 0.58, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-000000000014', 2);
