INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('story_retelling', '{"story": "A gate agent noticed a family about to miss their connecting flight due to a terminal change. Instead of letting them struggle, she personally guided them through the shortcut route. They made the flight with only minutes to spare. The family thanked her sincerely before boarding."}'::jsonb, null, 47, 0.52, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-00000000001a', 1),
('story_retelling', '{"story": "A transit driver noticed a regular passenger seemed unusually distressed one morning. He gently asked if everything was alright. She explained she was running late for an important interview. He radioed ahead so she could catch a connecting bus immediately on arrival."}'::jsonb, null, 45, 0.54, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-00000000001a', 2),
('story_retelling', '{"story": "An airport security team noticed long lines forming every morning during peak travel hours. Instead of simply adding more staff, they analyzed the checkpoint layout and found a bottleneck at bag inspection. Rearranging the stations reduced average wait times considerably."}'::jsonb, null, 44, 0.53, 'B2', 'approved', 'exam', 'business', 'd5000000-0000-4000-8000-00000000001a', 3);
